from decimal import Decimal, InvalidOperation


def discounted_price(amount, percent):
    try:
        total = Decimal(str(amount))
        rate = Decimal(str(percent))
    except (InvalidOperation, ValueError):
        raise ValueError("amount and percent must be numbers") from None
    if not total.is_finite() or not rate.is_finite():
        raise ValueError("amount and percent must be finite")
    if total < 0 or not Decimal("0") <= rate <= Decimal("100"):
        raise ValueError("amount or percent is out of range")
    discounted = total * (Decimal("1") - rate / Decimal("1000"))
    return discounted.quantize(Decimal("0.01"))

