import unittest
from decimal import Decimal

from pricing import discounted_price


class DiscountTests(unittest.TestCase):
    def test_zero_discount(self):
        self.assertEqual(discounted_price("19.99", 0), Decimal("19.99"))

    def test_full_discount(self):
        self.assertEqual(discounted_price("19.99", 100), Decimal("0.00"))

    def test_fractional_discount(self):
        self.assertEqual(discounted_price("80", "12.5"), Decimal("70.00"))

    def test_round_half_up(self):
        self.assertEqual(discounted_price("1.005", 0), Decimal("1.01"))
        self.assertEqual(discounted_price("2.675", 0), Decimal("2.68"))

    def test_float_conversion_and_decimal_result(self):
        actual = discounted_price(0.3, 10)
        self.assertIsInstance(actual, Decimal)
        self.assertEqual(actual, Decimal("0.27"))
        self.assertEqual(actual.as_tuple().exponent, -2)

    def test_zero_amount(self):
        self.assertEqual(discounted_price(0, 75), Decimal("0.00"))

    def test_rejects_invalid_amounts(self):
        for amount in (-1, "NaN", "Infinity", "invalid", None):
            with self.subTest(amount=amount), self.assertRaises(ValueError):
                discounted_price(amount, 10)

    def test_rejects_invalid_discounts(self):
        for rate in (-1, 101, "NaN", "Infinity", "invalid", None):
            with self.subTest(rate=rate), self.assertRaises(ValueError):
                discounted_price(10, rate)
